tool_input.new_string:
  /* 以模板项为唯一来源，按 templateItemId 去重（防止同 id 重复提交 / 空值项） */
  const seen = new Set<string>()
  const cleanItems: FloodItem[] = []
  for (const it of items.value) {
    const id = String(it.templateItemId)
    if (!id || seen.has(id)) continue
    seen.add(id)
    cleanItems.push({ ...it, templateItemId: id, value: it.value ?? '' })
  }
  return {
    eventId: String(eventId.value),
    complexId: String(complexId.value),
    complexName: complexName.value,
    checkDate: kind.value === 'pre' ? String(form.date ?? '') : undefined,
    haveDanger: '0',
    items: cleanItems,
  }
}
